<main class="auth-layout"><div class="auth-brand-panel"><a class="brand brand--light" href="<?= url() ?>"><img src="<?= photo(setting('logo')) ?>" width="55" height="55" alt=""><span><strong>SHREE JI</strong><small>GAS INDUSTRIES</small></span></a><div><span class="eyebrow">YOUR WEBSITE, IN YOUR HANDS</span><h1>A little care.<br>Behind the scenes.</h1><p>Manage your products, share your stories and keep your customers connected.</p></div><span>Shree Ji Gas Industries · Admin workspace</span></div><div class="auth-form-panel"><div class="auth-form"><span class="eyebrow">ADMIN WORKSPACE</span><h2><?= $setup?'Make yourself at home.':'Welcome back.' ?></h2><p><?= $setup?'Create your first administrator account.':'Sign in to look after your website.' ?></p><?php if($error): ?><div class="admin-alert admin-alert--error" role="alert"><?= e($error) ?></div><?php endif ?><?php if(!$hasAdmin&&!$setup): ?><div class="admin-alert">Your website is ready for its first administrator. <?= $canSetup?'Create your account to start editing.':'Set APP_SETUP_TOKEN on the server to enable secure account creation.' ?></div><?php if($canSetup): ?><a href="<?= url('admin/setup') ?>" class="btn btn-primary">Create admin account <?= icon('arrow-right-line') ?></a><?php endif ?><?php else: ?><form method="post" action="<?= url($setup?'admin/setup':'admin/login') ?>"><?= csrfField() ?><?php if($setup): ?><label for="adminName">Your name</label><input id="adminName" name="name" required minlength="2" maxlength="150" autocomplete="name"><label for="adminUsername">Username</label><input id="adminUsername" name="username" required pattern="[A-Za-z0-9._-]{3,100}" maxlength="100" autocomplete="username"><small>Use this username or your email whenever you sign in.</small><?php endif ?><label for="adminEmail"><?= $setup?'Email address':'Username or email' ?></label><input id="adminEmail" name="<?= $setup?'email':'identifier' ?>" type="<?= $setup?'email':'text' ?>" required autocomplete="username" maxlength="254"><label for="adminPassword">Password</label><input id="adminPassword" name="password" type="password" required <?= $setup?'minlength="12" maxlength="72" autocomplete="new-password"':'autocomplete="current-password"' ?>><?php if($setup): ?><small>Use at least 12 characters.</small><?php if(!Auth::localSetup()): ?><label for="setupToken">Installation token</label><input id="setupToken" name="setup_token" type="password" required autocomplete="off"><?php endif ?><?php endif ?><button class="btn btn-primary" type="submit"><?= $setup?'Create account':'Sign in' ?> <?= icon('arrow-right-line') ?></button></form><?php if(!$setup): ?><a class="auth-forgot" href="<?= url('admin/forgot') ?>">Forgot password?</a><?php endif ?><?php endif ?><a class="auth-back" href="<?= url() ?>"><?= icon('arrow-left-line') ?> Back to the website</a></div></div></main>
